SELECT CASE WHEN c.credit_limit >= 14000 THEN 'high' WHEN c.credit_limit >= 7800 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, ROUND(STDDEV(a.balance), 2) AS stddev_balance FROM accounts a JOIN customers c ON c.id = a.customer_id WHERE MONTH(a.opened_date) IN (1, 8, 11) GROUP BY CASE WHEN c.credit_limit >= 14000 THEN 'high' WHEN c.credit_limit >= 7800 THEN 'mid' ELSE 'low' END ORDER BY credit_limit_bucket, stddev_balance DESC;
